#!/usr/bin/env node

/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * RADIANCE PLATFORM — JAVASCRIPT BUNDLE & CHUNK AUDITOR
 * 
 * Inspects production build artifacts generated by Next.js in `.next/`
 * to accurately measure uncompressed and compressed chunk sizes, route footprints,
 * and verify adherence to performance budgets.
 * ═══════════════════════════════════════════════════════════════════════════════
 */

import fs from "fs";
import path from "path";
import zlib from "zlib";

const NEXT_DIR = path.resolve(process.cwd(), ".next");
const APP_MANIFEST_PATH = path.join(NEXT_DIR, "app-build-manifest.json");

// Realistic Empirical Performance Budgets established from verified Next.js 15 baseline
const BUDGETS = {
  "/page": { maxGzipKb: 800, maxRawKb: 3000 },
  "/layout": { maxGzipKb: 220, maxRawKb: 850 },
  "/_not-found/page": { maxGzipKb: 200, maxRawKb: 750 },
};

function formatSize(bytes) {
  return `${(bytes / 1024).toFixed(1)} kB`;
}

function getFileSize(filePath) {
  try {
    const buffer = fs.readFileSync(filePath);
    const raw = buffer.length;
    const gzip = zlib.gzipSync(buffer).length;
    return { raw, gzip };
  } catch {
    return { raw: 0, gzip: 0 };
  }
}

async function runBundleAudit() {
  console.log("══════════════════════════════════════════════════════════════");
  console.log(" RADIANCE PLATFORM — CLIENT JAVASCRIPT BUNDLE AUDIT");
  console.log("══════════════════════════════════════════════════════════════\n");

  if (!fs.existsSync(APP_MANIFEST_PATH)) {
    console.error("Error: .next/app-build-manifest.json not found. Run 'pnpm build' first.");
    process.exit(1);
  }

  const manifest = JSON.parse(fs.readFileSync(APP_MANIFEST_PATH, "utf8"));
  let hasBudgetViolation = false;

  console.log(`| Route               | Raw Size   | Gzip Size  | Budget (Gzip) | Status |`);
  console.log(`|:--------------------|:-----------|:-----------|:--------------|:-------|`);

  for (const [route, chunks] of Object.entries(manifest.pages)) {
    let totalRaw = 0;
    let totalGzip = 0;

    for (const chunk of chunks) {
      const chunkPath = path.join(NEXT_DIR, chunk);
      const { raw, gzip } = getFileSize(chunkPath);
      totalRaw += raw;
      totalGzip += gzip;
    }

    const budget = BUDGETS[route];
    let status = "PASS";
    const budgetStr = budget ? `< ${budget.maxGzipKb} kB` : "N/A";

    if (budget && (totalGzip / 1024) > budget.maxGzipKb) {
      status = "FAIL (EXCEEDED)";
      hasBudgetViolation = true;
    }

    console.log(
      `| ${route.padEnd(19)} | ${formatSize(totalRaw).padEnd(10)} | ${formatSize(totalGzip).padEnd(10)} | ${budgetStr.padEnd(13)} | ${status} |`
    );
  }

  console.log("\n══════════════════════════════════════════════════════════════");
  if (hasBudgetViolation) {
    console.error("❌ Bundle budget exceeded. Review chunk size regressions.");
    process.exit(1);
  } else {
    console.log("✅ All evaluated routes are within performance budgets.");
    process.exit(0);
  }
}

runBundleAudit();
